import {html} from '/vendor/preact-htm.mjs';
import {mLong,mk} from '/insights.mjs';
import {BankLogo,LinkPill,SR,Select,Switch,title} from '/ui.js';
import {H2,Sub,card,grid2,AskBtn,chartView,paras,MoneyInput,inputSt,fieldLabel} from '/pages.js';

const chip=a=>`border:1px solid ${a?'#183c35':'#cdd6ca'};background:${a?'#183c35':'#fff'};color:${a?'#fff':'#183c35'}`;
const Chips=({opts,label,pad='7px 14px'})=>html`<div role="group" aria-label=${label} style="display:flex;gap:6px;flex-wrap:wrap">${opts.map(o=>html`<button onClick=${o.go} aria-pressed=${o.a} style=${`${chip(o.a)};border-radius:999px;padding:${pad};font-size:13px;font-weight:600;cursor:pointer`}>${o.label}</button>`)}</div>`;
const legend=t=>html`<legend style="font:600 14px 'Geist',sans-serif;margin-bottom:8px">${t}</legend>`;
const fs='border:0;margin:0;padding:0;display:grid;gap:6px';
const btn='background:#fff;border:1px solid #cdd6ca;padding:9px 14px;border-radius:8px;font-size:13px;font-weight:600;color:#183c35;cursor:pointer';
const btnDark='background:#183c35;border:1px solid #183c35;padding:9px 14px;border-radius:8px;font-size:13px;font-weight:600;color:#fff;cursor:pointer';

// ===================== PROJECTIONS =====================
export function Projections({A,S,J,pad,gap,mobile}){
 const pl=J.plan({cuts:S.cuts,cancel:S.cancel,incomeChange:S.incChg,oneOff:S.oneOff,oneOffMonth:S.oneOffMonth});
 if(!pl.months)return html`<section style=${card(pad)}><${H2}>Not enough history yet</${H2}><p style="margin:0;color:#3d4d45">Projections need at least one complete month of transactions. Sync your accounts and check back after the month ends.</p></section>`;
 const now=pl.sc[0],endB=pl.base.at(-1),endS=pl.sc.at(-1),anyChange=Math.abs(pl.keptScen-pl.keptBase)>.5||S.oneOff>0,endLabel=pl.dates.at(-1).toLocaleDateString('en-CA',{month:'long',year:'numeric'}),dKept=pl.keptScen-pl.keptBase,ml=i=>pl.dates[i-1].toLocaleDateString('en-CA',{month:'short',year:'numeric'});
 const tiles=[{label:'Coming in',value:A.money(pl.incScen),note:'per month',fg:'#fff'},{label:'Going out',value:A.money(pl.outScen),note:'per month',fg:'#fff'},{label:'You keep',value:A.money(pl.keptScen),note:anyChange&&dKept?`${dKept>0?'+':'−'}${A.money(Math.abs(dKept))} vs today`:'per month',fg:'#d1e5a7'},{label:'Over a year',value:A.money(endS-now),note:'saved in total',fg:'#d1e5a7'}];
 const cutNames=['Dining out','Shopping','Groceries','Transport'].filter(n=>pl.groups.some(g=>g.name===n));
 const subRows=pl.subs.filter(x=>['Entertainment','Services','Personal care'].includes(x.category));
 const lo=Math.min(...pl.base,...pl.sc),hi=Math.max(...pl.base,...pl.sc),pd=(hi-lo)*.12||500,L=lo-pd,Hh=hi+pd,W=800,H=240;
 const scP=J.linePath(pl.sc,W,H,14,L,Hh),bP=J.linePath(pl.base,W,H,14,L,Hh);
 const minV=Math.min(...pl.sc),minI=pl.sc.indexOf(minV);
 const chartNote=S.oneOff&&minI>0?`Your balance dips to ${A.money(minV)} in ${ml(minI)} after the ${A.money(S.oneOff)} expense, then ${pl.keptScen>0?'keeps growing':'keeps falling'}.`:pl.keptScen>=0?`Your balance grows by about ${A.money(pl.keptScen)} most months. Months that usually cost more, like December, grow less.`:`Your balance shrinks by about ${A.money(-pl.keptScen)} most months at this pace.`;
 const reach=series=>{for(let i=1;i<series.length;i++)if(series[i]-series[0]>=S.goal)return i;const k=(series.at(-1)-series[0])/12;return k>0?Math.ceil(S.goal/k):null;},rb=reach(pl.base),rs=reach(pl.sc),dl=i=>new Date(J.TODAY.getFullYear(),J.TODAY.getMonth()+i,1).toLocaleDateString('en-CA',{month:'long',year:'numeric'}),r1=anyChange?rs:rb;
 const ess=['Rent','Loan payments','Bills & subscriptions','Groceries'].reduce((a,n)=>a+(pl.groups.find(g=>g.name===n)?.base||0),0),mo=ess>0?Math.max(0,now)/ess:0;
 const notes=[],decY=J.TODAY.getFullYear()-1,dec=J.monthly(`${decY}-12-01`,`${decY}-12-31`)[0],flex=pl.groups.filter(g=>g.flexible).sort((a,b)=>b.base-a.base)[0],rent=pl.groups.find(g=>g.name==='Rent'),subY=pl.subs.reduce((a,x)=>a+x.yearly,0);
 if(dec&&dec.spending>pl.outBase*1.05&&`${decY}-12`>=J.minMonth)notes.push({icon:'❄',bg:'#e3ecf6',fg:'#2c5577',head:'December costs more.',body:`Last December you spent ${A.money(dec.spending-pl.outBase)} more than a typical month. Worth setting aside a little in November.`});
 if(flex)notes.push({icon:'◷',bg:'#f8e6e0',fg:'#9a3d2a',head:`${flex.name} is your biggest flexible cost.`,body:`About ${A.money(flex.base)} a month. A 25% cut would free up ${A.money(flex.base*.25)}.`});
 if(rent&&pl.income>0)notes.push({icon:'⌂',bg:'#eef1ea',fg:'#3d4d45',head:`Rent takes ${Math.round(rent.base/pl.income*100)}% of your income.`,body:'Anything under about a third is generally considered comfortable.'});
 if(subY>0)notes.push({icon:'↻',bg:'#e6f0dc',fg:'#2f5d3a',head:`Bills & subscriptions: ${A.money(subY)} a year.`,body:'Cancelling even one or two adds up quickly.'});
 const askScenario=()=>A.ask(`I'm planning these changes: ${Object.entries(S.cuts).filter(([,v])=>v).map(([k,v])=>`spend ${v}% less on ${k}`).join(', ')||'no spending cuts'}; cancel ${S.cancel.map(n=>title(n)).join(', ')||'no subscriptions'}; income change ${A.money(S.incChg)}/month; one-off expense ${A.money(S.oneOff)}. Is this realistic given my actual spending, and what's the easiest place to start?`);
 return html`
  <section aria-labelledby="hero-h" style=${`background:#183c35;color:#fff;border-radius:18px;padding:${mobile?'22px':'32px'};display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,320px),1fr));gap:24px;align-items:center`}>
   <div style="display:grid;gap:10px;min-width:0">
    <span style="font-size:13px;font-weight:700;letter-spacing:.6px;text-transform:uppercase;color:#d1e5a7">${anyChange?'With your changes':'If things stay as they are'}</span>
    <h2 id="hero-h" style="margin:0;font:400 24px/1.35 'Instrument Serif',serif;color:#fff;text-wrap:pretty">By ${endLabel}, you’re on track to have</h2>
    <div style=${`font:400 ${mobile?48:62}px/1 'Instrument Serif',serif;letter-spacing:-.3px;font-variant-numeric:tabular-nums`}>${A.money(anyChange?endS:endB)}</div>
    <p style="margin:0;font-size:15px;line-height:1.55;color:#d6e5d0;text-wrap:pretty">${anyChange?`in the bank. That’s ${endS>=endB?A.money(endS-endB)+' more':A.money(endB-endS)+' less'} than if nothing changes, and ${endS>=now?A.money(endS-now)+' more':A.money(now-endS)+' less'} than today.`:`in the bank, ${endB>=now?'up':'down'} ${A.money(Math.abs(endB-now))} from ${A.money(now)} today. Try a change below to see how it moves.`}</p>
   </div>
   <div style="display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px">${tiles.map(h=>html`<div style="background:#ffffff12;border:1px solid #ffffff26;border-radius:12px;padding:14px;min-width:0"><div style="font-size:13px;color:#d6e5d0">${h.label}</div><div style=${`font:400 26px/1.25 'Instrument Serif',serif;margin-top:4px;color:${h.fg};font-variant-numeric:tabular-nums`}>${h.value}</div><div style="font-size:12px;color:#d6e5d0;margin-top:2px">${h.note}</div></div>`)}</div>
  </section>
  <div style=${grid2(gap)}>
   <section aria-labelledby="month-h" style=${card(pad)}>
    <div><${H2} id="month-h">Your typical month</${H2}><${Sub}>Based on your last ${pl.months} month${pl.months>1?'s':''}: what comes in, and where it goes</${Sub}></div>
    <div style="display:grid;gap:6px;background:#eef5e8;border-radius:10px;padding:12px"><div style="display:flex;justify-content:space-between;gap:10px;font-size:14px"><b>Money in <span style="font-weight:400;color:#3d4d45">· income</span></b><span style="font-variant-numeric:tabular-nums">${S.incChg?html`<s style="color:#5a6b63;margin-right:6px">${A.money(pl.income)}</s>`:null}<b style="color:#2f5d3a">${A.money(pl.incScen)}</b></span></div><div style="height:10px;background:#315e4e;border-radius:6px"></div></div>
    <div style="display:grid;gap:2px">${pl.groups.map(g=>{const changed=Math.abs(g.scen-g.base)>.5,base=Math.max(1,pl.income);return html`<div style=${`display:grid;grid-template-columns:${mobile?'minmax(96px,120px)':'minmax(110px,150px)'} minmax(0,1fr) auto;gap:12px;align-items:center;padding:7px 0;font-size:14px`}><span style="font-weight:600;display:flex;align-items:center;gap:6px;flex-wrap:wrap">${g.name}${!g.flexible?html`<span title="Fixed cost" style="font-size:11px;font-weight:700;color:#3d4d45;background:#eef1ea;border-radius:8px;padding:1px 6px">fixed</span>`:null}</span><div style="position:relative;height:10px;background:#f3f5f0;border-radius:6px"><div style=${`position:absolute;inset:0 auto 0 0;width:${Math.min(100,g.base/base*100)}%;background:#ecd6c6;border-radius:6px`}></div><div style=${`position:absolute;inset:0 auto 0 0;width:${Math.min(100,g.scen/base*100)}%;background:#c47a4e;border-radius:6px;transition:width .25s`}></div></div><span style="font-variant-numeric:tabular-nums;text-align:right;white-space:nowrap">${changed?html`<s style="color:#5a6b63;margin-right:6px">${A.money(g.base)}</s>`:null}<b>${A.money(g.scen)}</b></span></div>`;})}</div>
    <div style="display:flex;justify-content:space-between;align-items:center;gap:12px;border-top:2px solid #183c35;padding-top:12px;flex-wrap:wrap"><div><b style="font:600 15px 'Geist',sans-serif">Left over each month</b><div style="font-size:13px;color:#5a6b63">${pl.keptScen>0&&pl.incScen>0?`About ${Math.round(pl.keptScen/pl.incScen*100)}¢ of every dollar you earn`:'You’re spending more than you earn'}</div></div><div style="text-align:right">${anyChange?html`<s style="color:#5a6b63;margin-right:8px;font-variant-numeric:tabular-nums">${A.money(pl.keptBase)}</s>`:null}<b style=${`font:400 31px/1.1 'Instrument Serif',serif;letter-spacing:-.8px;color:${pl.keptScen>=0?'#2f5d3a':'#9a3d2a'};font-variant-numeric:tabular-nums`}>${A.money(pl.keptScen)}</b></div></div>
   </section>
   <section aria-labelledby="try-h" style=${`background:#f0f4e8;border:1px solid #dfe6d6;border-radius:14px;padding:${pad};display:grid;gap:18px;min-width:0`}>
    <div style="display:flex;justify-content:space-between;gap:12px;align-items:flex-start"><div><${H2} id="try-h">Try a change</${H2}><${Sub} fg="#4d5d55">Pick what you’d realistically do. Everything updates instantly.</${Sub}></div><button onClick=${()=>A.setState({cuts:{},cancel:[],incChg:0,oneOff:0,oneOffMonth:6})} style="background:#fff;border:1px solid #cdd6ca;padding:6px 12px;border-radius:8px;font-size:13px;font-weight:600;color:#183c35;cursor:pointer;flex:none">Reset</button></div>
    ${cutNames.length?html`<fieldset style=${fs+';gap:10px'}>${legend('Spend less on…')}${cutNames.map(n=>{const g=pl.groups.find(x=>x.name===n),c=S.cuts[n]||0;return html`<div style="display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap;background:#fff;border-radius:10px;padding:8px 8px 8px 12px"><div style="min-width:0"><div style="font-size:14px;font-weight:600">${n}</div><div style=${`font-size:12px;color:${c?'#2f5d3a':'#4d5d55'}`}>${c?`Saves ${A.money(g.base*c/100)} a month`:`You spend about ${A.money(g.base)} a month`}</div></div><div role="group" aria-label=${`Cut ${n}`} style="display:flex;gap:2px;background:#edf0e9;border-radius:8px;padding:3px">${[0,10,25,50].map(p=>{const a=c===p;return html`<button onClick=${()=>A.setState(st=>({cuts:{...st.cuts,[n]:p}}))} aria-pressed=${a} style=${`border:0;border-radius:6px;padding:6px 10px;font-size:13px;font-weight:${a?700:500};background:${a?'#183c35':'transparent'};color:${a?'#fff':'#3d4d45'};cursor:pointer;min-width:44px`}>${p?`−${p}%`:'Same'}</button>`;})}</div></div>`;})}</fieldset>`:null}
    ${subRows.length?html`<fieldset style=${fs}>${legend('Cancel a subscription')}<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(min(100%,190px),1fr));gap:6px">${subRows.map(x=>{const on=S.cancel.includes(x.name);return html`<button type="button" role="checkbox" aria-checked=${on} onClick=${()=>A.setState(st=>({cancel:on?st.cancel.filter(y=>y!==x.name):[...st.cancel,x.name]}))} class="hv-border2" style=${`display:flex;align-items:center;gap:10px;background:${on?'#fff':'#ffffffa6'};border:1px solid ${on?'#315e4e':'#dfe6d6'};border-radius:10px;padding:9px 12px;cursor:pointer;font-size:14px;text-align:left;color:#183c35;transition:background .15s,border-color .15s`}><span aria-hidden="true" style=${`width:20px;height:20px;border-radius:6px;border:2px solid ${on?'#315e4e':'#9fb09a'};background:${on?'#315e4e':'#fff'};color:#fff;display:grid;place-items:center;font-size:12px;font-weight:800;flex:none;transition:background .15s`}>${on?'✓':''}</span><span style=${`flex:1;min-width:0;font-weight:600;text-decoration:${on?'line-through':'none'}`}>${title(x.name)}</span><span style="font-size:13px;color:#3d4d45;font-variant-numeric:tabular-nums">${A.money(x.amount,2)}</span></button>`;})}</div></fieldset>`:null}
    <fieldset style=${fs}>${legend('Earn more each month')}<${Chips} label="Extra income" opts=${[0,250,500,1000].map(v=>({label:v?`+${A.money(v)}`:'No change',a:S.incChg===v,go:()=>A.setState({incChg:v})}))}/></fieldset>
    <fieldset style=${fs}>${legend('A big expense coming up?')}<div style="display:flex;gap:6px;flex-wrap:wrap;align-items:center"><${Chips} label="One-off expense" opts=${[[0,'None'],[1000,'$1,000'],[2500,'$2,500'],[5000,'$5,000'],[10000,'$10,000']].map(([v,l])=>({label:l,a:S.oneOff===v,go:()=>A.setState({oneOff:v})}))}/>${S.oneOff>0?html`<span style="font-size:13px;font-weight:600">in</span><${Select} value=${S.oneOffMonth} options=${pl.dates.map((d,i)=>({value:i+1,label:d.toLocaleDateString('en-CA',{month:'long',year:'numeric'})}))} onChange=${v=>A.setState({oneOffMonth:+v})} label="Month of expense" hideLabel=${true} size="sm" minWidth="180px" icon="calendar"/>`:null}</div></fieldset>
    <div style="background:#183c35;color:#fff;border-radius:12px;padding:14px 16px;display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap" aria-live="polite"><div><b style="font:600 15px 'Geist',sans-serif">${anyChange?(dKept>=0?`You’d keep ${A.money(dKept)} more a month`:`You’d keep ${A.money(-dKept)} less a month`):'No changes yet'}</b><div style="font-size:13px;color:#d6e5d0">${anyChange?`That’s ${A.money(Math.abs(dKept*12))} over a year${S.oneOff?`, minus a one-off ${A.money(S.oneOff)}`:''}.`:'Pick something above to see the difference.'}</div></div><${AskBtn} label="✦ Ask if it’s realistic" fill="#d1e5a7" rest="#d1e5a7" extra="font-weight:700" onClick=${askScenario}/></div>
   </section>
  </div>
  <section aria-labelledby="bal-h" style=${card(pad)}>
   <div style="display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap"><div><${H2} id="bal-h">Your bank balance, month by month</${H2}><${Sub}>Chequing and savings combined</${Sub}></div>
    <div style="display:flex;gap:16px;font-size:13px;color:#3d4d45;align-items:center;flex-wrap:wrap"><span style="display:flex;align-items:center;gap:6px"><i style="width:18px;border-top:2px dashed #6b7a72"></i>As things are · <b>${A.money(endB)}</b></span>${anyChange?html`<span style="display:flex;align-items:center;gap:6px"><i style="width:18px;height:3px;background:#315e4e;border-radius:2px"></i>With your changes · <b style="color:#2f5d3a">${A.money(endS)}</b></span>`:null}</div></div>
   <div style="position:relative"><svg viewBox="0 0 800 240" preserveAspectRatio="none" role="img" aria-label=${`Bank balance over 12 months: from ${A.money(now)} today to ${A.money(endB)} as things are${anyChange?`, or ${A.money(endS)} with your changes`:''}`} style="width:100%;height:240px;display:block">${[0,1,2,3].map(i=>html`<line x1="0" x2="800" y1=${14+i*(H-28)/3} y2=${14+i*(H-28)/3} stroke="#eef1ea"></line>`)}<path d=${(anyChange?scP:bP).area} fill="#d1e5a7" fill-opacity=".4"></path><path d=${bP.d} fill="none" stroke="#6b7a72" stroke-width="2" stroke-dasharray="6 5" vector-effect="non-scaling-stroke"></path><path d=${anyChange?scP.d:bP.d} fill="none" stroke="#315e4e" stroke-width="3" vector-effect="non-scaling-stroke"></path></svg>
    ${[0,1,2].map(i=>{const v=Hh-(Hh-L)*i/3;return html`<span aria-hidden="true" style=${`position:absolute;left:4px;top:${14+i*(H-28)/3-9}px;font-size:12px;color:#5a6b63;background:#ffffffd9;padding:0 4px;border-radius:4px`}>${A.short(v)}</span>`;})}</div>
   <div aria-hidden="true" style="display:flex;justify-content:space-between;font-size:12px;color:#5a6b63;margin-top:-8px">${pl.labels.filter((x,i)=>i%2===0).map(t=>html`<span>${t}</span>`)}</div>
   <p style="margin:0;font-size:14px;color:#3d4d45;text-wrap:pretty">${chartNote}</p>
  </section>
  <div style=${`display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,300px),1fr));gap:${gap};align-items:stretch`}>
   <section aria-labelledby="goal-h" style=${card(pad,'gap:12px;align-content:start')}>
    <${H2} id="goal-h">Saving for something?</${H2}>
    <${Chips} label="Savings goal" pad="6px 12px" opts=${[5000,10000,25000,50000].map(v=>({label:A.short(v).replace('.0k','k'),a:S.goal===v,go:()=>A.setState({goal:v})}))}/>
    <div style="font:400 26px/1.3 'Instrument Serif',serif;letter-spacing:-.4px;text-wrap:pretty">${r1?`You’d have ${A.money(S.goal)} saved by ${dl(r1)}`:'Not reachable yet at this pace'}</div>
    <div style="height:10px;background:#edf1e9;border-radius:6px;overflow:hidden"><div style=${`height:100%;width:${Math.min(100,Math.max(2,(pl.sc.at(-1)-now)/S.goal*100))}%;background:#315e4e;border-radius:6px;transition:width .25s`}></div></div>
    <p style="margin:0;font-size:13px;color:#5a6b63;text-wrap:pretty">${anyChange&&rs&&rb&&rb>rs?`That’s ${rb-rs} month${rb-rs>1?'s':''} sooner than if nothing changes (${dl(rb)}).`:r1?`That’s about ${r1} month${r1>1?'s':''} of saving at your current pace. Try a change to get there sooner.`:'Try cutting some spending to start saving each month.'}</p>
   </section>
   <section aria-labelledby="safe-h" style=${card(pad,'gap:12px;align-content:start')}>
    <div style="display:flex;justify-content:space-between;gap:8px;align-items:center"><${H2} id="safe-h">Your safety net</${H2}><span style=${`font-size:12px;font-weight:700;padding:3px 9px;border-radius:20px;background:${mo>=3?'#e6f0dc':'#fbefd9'};color:${mo>=3?'#2f5d3a':'#7a5520'}`}>${mo>=6?'Strong':mo>=3?'Healthy':'Building'}</span></div>
    <div style="display:flex;align-items:baseline;gap:8px"><span style="font:400 43px/1 'Instrument Serif',serif;letter-spacing:-1px">${mo.toFixed(1)}</span><span style="font-size:14px;color:#3d4d45">months covered</span></div>
    <div style="position:relative;height:10px;background:#edf1e9;border-radius:6px"><div style=${`height:100%;width:${Math.min(100,mo/6*50)}%;background:#315e4e;border-radius:6px`}></div><div aria-hidden="true" style="position:absolute;left:50%;top:-4px;bottom:-4px;width:2px;background:#183c35;opacity:.45"></div></div>
    <p style="margin:0;font-size:13px;color:#5a6b63;text-wrap:pretty">If your income stopped, today’s ${A.money(now)} would cover rent, loan payments, bills and groceries (${A.money(ess)} a month) for about ${mo.toFixed(1)} months. The line marks 6 months, a common target.</p>
   </section>
   <section aria-labelledby="heads-h" style=${card(pad,'gap:10px;align-content:start')}>
    <${H2} id="heads-h">Good to know</${H2}>
    <ul style="list-style:none;margin:0;padding:0;display:grid;gap:10px">${notes.map(n=>html`<li style="display:flex;gap:10px;align-items:flex-start;font-size:14px;line-height:1.5"><span aria-hidden="true" style=${`width:28px;height:28px;border-radius:8px;background:${n.bg};color:${n.fg};display:grid;place-items:center;flex:none;font-size:14px`}>${n.icon}</span><span style="text-wrap:pretty"><b>${n.head}</b> ${n.body}</span></li>`)}</ul>
   </section>
  </div>
  <details style="background:#fff;border:1px solid #e2e7df;border-radius:14px;padding:14px 18px"><summary style="cursor:pointer;font-weight:600;font-size:14px">How is this worked out?</summary><p style="margin:10px 0 0;font-size:14px;color:#3d4d45;line-height:1.6;text-wrap:pretty">We take your average month from the last ${pl.months} complete month${pl.months>1?'s':''} (what came in and what went out) and repeat it forward from today’s chequing and savings balance of ${A.money(now)}. Months that have cost more in the past, like December, get a little extra. Paying off your credit cards, moving money into savings and purchases that were paid back to you aren’t counted as spending, since the money stays yours. It’s a guide to help you plan, not a promise.</p></details>`;
}

// ===================== TRANSACTIONS =====================
const KINDS={income:'Income',refund:'Refund',credit_payment:'Card payment',transfer:'Transfer',contribution:'Household contribution',reimbursement:'Reimbursement',reimbursed_expense:'Paid back to you'};
export function Transactions({A,S,J,rows,all,pad,rowPad}){
 const builtIn=[{id:'all',label:'All'},{id:'subs',label:'Bills & subscriptions'},{id:'large',label:'Over $200'},{id:'dining',label:'Dining out',tCat:'Food & dining'},{id:'income',label:'Income',tType:'income'}];
 const vlist=[...builtIn,...S.views.map(v=>({...v,custom:true}))];
 const q=S.q.trim().toLowerCase();
 let tr=rows.filter(t=>(!q||`${t.name} ${t.category} ${t.accountName} ${t.institution}`.toLowerCase().includes(q))&&(!S.tCat||t.category===S.tCat)&&(S.tType==='all'||t.kind===S.tType||S.tType==='reimbursement'&&t.kind==='reimbursed_expense')&&(S.view!=='subs'||t.sub||t.fixed)&&(S.view!=='large'||Math.abs(t.amount)>=200&&t.kind==='expense'));
 const {key,dir}=S.sort;tr=[...tr].sort((a,b)=>{const x=key==='amount'?a.amount-b.amount:String(a[key]??'').localeCompare(String(b[key]??''),undefined,{numeric:true,sensitivity:'base'});return dir==='asc'?x:-x;});
 const outSum=tr.filter(t=>t.kind==='expense'&&!t.pending).reduce((a,t)=>a+t.amount,0),inSum=-tr.filter(t=>['income','refund','contribution'].includes(t.kind)&&!t.pending).reduce((a,t)=>a+t.amount,0);
 const catOpts=[...new Set(all.map(t=>t.category).filter(Boolean))].sort((a,b)=>a.localeCompare(b));
 const cols=[['date','Date','left'],['name','Merchant','left'],['category','Category','left'],['accountName','Account','left'],['amount','Amount','right']];
 const saveView=()=>{const label=[S.q&&`“${S.q}”`,S.tCat,S.tType!=='all'&&(KINDS[S.tType]||S.tType)].filter(Boolean).join(' · ')||'My view',id='v'+Date.now();A.setState(st=>({views:[...st.views,{id,label:label.slice(0,60),q:S.q,tCat:S.tCat,tType:S.tType}],view:id}));A.toast(`Saved view: ${label}`);};
 const saveEdit=()=>{const t=J.tx.find(x=>x.id===S.editTx);if(!t)return;if(S.editRule){A.setState(st=>({rules:{...st.rules,[t.name]:S.editCat},editTx:''}));A.toast(`Rule saved: ${title(t.name)} → ${S.editCat}`);}else{A.setState(st=>({overrides:{...st.overrides,[t.id]:S.editCat},editTx:''}));A.toast('Category updated');}};
 return html`
  <div role="group" aria-label="Saved views" style="display:flex;gap:8px;flex-wrap:wrap;align-items:center">
   ${vlist.map(v=>{const a=S.view===v.id;return html`<span style=${`display:inline-flex;align-items:center;background:${a?'#183c35':'#fff'};border:1px solid ${a?'#183c35':'#cdd6ca'};border-radius:20px`}><button onClick=${()=>A.setState({view:v.id,q:v.q||'',tCat:v.tCat||'',tType:v.tType||'all',limit:40,editTx:''})} aria-pressed=${a} style=${`border:0;background:transparent;color:${a?'#fff':'#183c35'};padding:7px 13px;font-size:13px;font-weight:600;cursor:pointer;border-radius:20px`}>${v.label}</button>${v.custom?html`<button onClick=${()=>A.setState(st=>({views:st.views.filter(x=>x.id!==v.id),view:'all'}))} aria-label=${`Delete view ${v.label}`} style=${`border:0;background:transparent;color:${a?'#fff':'#183c35'};padding:7px 10px 7px 0;cursor:pointer`}>✕</button>`:null}</span>`;})}
   <button onClick=${saveView} style="border:1px dashed #9fb09a;background:transparent;color:#2f5d3a;padding:7px 13px;font-size:13px;font-weight:600;cursor:pointer;border-radius:20px">＋ Save current filters</button>
  </div>
  <section aria-label="Transactions" style=${card(pad)}>
   <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,180px),1fr));gap:10px;align-items:end">
    <label style="display:grid;gap:5px;font-size:12px;font-weight:600;color:#3d4d45;grid-column:span 2;min-width:0">Search<span style="position:relative;display:flex;align-items:center"><svg aria-hidden="true" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#4f6b5e" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" style="position:absolute;left:12px;pointer-events:none"><circle cx="11" cy="11" r="7"></circle><path d="m20 20-3.5-3.5"></path></svg><input value=${S.q} onInput=${e=>A.setState({q:e.target.value,limit:40,view:''})} placeholder="Merchant, category or account" class="fi" style=${inputSt+';min-height:42px;padding:10px 40px 10px 36px'}/>${S.q?html`<button type="button" onClick=${()=>A.setState({q:'',view:'all',limit:40})} aria-label="Clear search" class="hv-df" style="position:absolute;right:7px;width:28px;height:28px;border:0;border-radius:50%;background:#eef3e8;color:#183c35;cursor:pointer;font-size:12px">✕</button>`:null}</span></label>
    <${Select} value=${S.tCat} options=${[{value:'',label:'All categories'},...catOpts.map(c=>({value:c,label:c}))]} onChange=${v=>A.setState({tCat:v,limit:40,view:''})} label="Category" icon="tag" width="100%" minWidth="0"/>
    <${Select} value=${S.tType} options=${[['all','All types'],['expense','Expenses'],['income','Income'],['contribution','Household contributions'],['refund','Refunds'],['reimbursement','Paid back to you'],['credit_payment','Card payments'],['transfer','Transfers']].map(([value,label])=>({value,label}))} onChange=${v=>A.setState({tType:v,limit:40,view:''})} label="Type" icon="swap" width="100%" minWidth="0"/>
    <button onClick=${()=>A.setState({q:'',tCat:'',tType:'all',view:'all',limit:40})} style=${btn+';border-radius:10px;min-height:42px'}>Clear</button>
   </div>
   <div style="display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap;font-size:13px;color:#3d4d45" aria-live="polite"><span><b>${tr.length.toLocaleString()}</b> transactions · out <b>${A.money(outSum)}</b> · in <b style="color:#2f5d3a">${A.money(inSum)}</b></span><span style="color:#5a6b63">Select a category to recategorize</span></div>
   <div style="overflow-x:auto;margin:0 -4px"><table style="width:100%;border-collapse:collapse;font-size:14px;min-width:680px">
    <thead><tr>${cols.map(([k,l,al])=>{const a=key===k;return html`<th scope="col" aria-sort=${a?(dir==='asc'?'ascending':'descending'):'none'} style=${`text-align:${al};padding:0;background:#f5f7f2;font-weight:600;color:#3d4d45;font-size:12px;border-bottom:1px solid #e2e7df`}><button onClick=${()=>A.setState({sort:{key:k,dir:a&&dir==='desc'?'asc':a?'desc':(k==='date'||k==='amount'?'desc':'asc')}})} style=${`width:100%;border:0;background:transparent;text-align:${al};padding:10px 8px;font-size:12px;font-weight:600;color:#3d4d45;cursor:pointer;white-space:nowrap`}>${l} <span aria-hidden="true" style="color:#315e4e">${a?(dir==='asc'?'↑':'↓'):''}</span></button></th>`;})}</tr></thead>
    <tbody>${tr.slice(0,S.limit).map(t=>{const inc=t.amount<0,ed=S.editTx===t.id,nm=title(t.name),k=KINDS[t.kind];return html`
     <tr key=${t.id} style=${`border-bottom:1px solid #eef1ea;background:${ed?'#f7f9f4':['transfer','credit_payment'].includes(t.kind)?'#fafbf9':'#fff'}`}><td style=${`padding:${rowPad};white-space:nowrap;color:#3d4d45;font-variant-numeric:tabular-nums`}>${A.fmtDate(t.date)}</td><td style=${`padding:${rowPad}`}><span style="font-weight:600">${nm}</span>${k?html` <span style="font-size:11px;font-weight:700;background:#e9eef4;color:#3c5670;padding:2px 7px;border-radius:10px;margin-left:4px">${k}</span>`:null}${t.pending?html` <span style="font-size:11px;font-weight:700;background:#fbefd9;color:#7a5520;padding:2px 7px;border-radius:10px;margin-left:4px">Pending</span>`:null}${t.currency&&t.currency!=='CAD'?html` <span style="font-size:11px;font-weight:700;background:#eef1ea;color:#3d4d45;padding:2px 7px;border-radius:10px;margin-left:4px">${t.currency}</span>`:null}</td><td style=${`padding:${rowPad}`}><button onClick=${()=>A.setState({editTx:ed?'':t.id,editCat:t.category,editRule:true})} aria-label=${`Change category for ${nm}, currently ${t.category}`} aria-expanded=${ed} style="border:1px solid #dfe5db;background:#f3f6ef;border-radius:7px;padding:4px 9px;font-size:13px;color:#2f4a3f;cursor:pointer;white-space:nowrap">${t.category} <span aria-hidden="true">▾</span></button></td><td style=${`padding:${rowPad};color:#3d4d45`}><span style="display:flex;align-items:center;gap:8px;white-space:nowrap"><${BankLogo} institution=${t.institution} size=${16}/>${t.institution}${t.accountName?` · ${t.accountName}`:''}</span></td><td style=${`padding:${rowPad};text-align:right;white-space:nowrap;font-weight:600;font-variant-numeric:tabular-nums;color:${inc?'#2f5d3a':'#183c35'}`}><span aria-hidden="true">${(inc?'+':'−')+A.money(Math.abs(t.amount),2)}</span><${SR}>${inc?'received':'spent'} ${A.money(Math.abs(t.amount),2)}</${SR}></td></tr>
     ${ed?html`<tr><td colspan="5" style="padding:12px;background:#f7f9f4;border-bottom:1px solid #e2e7df"><div style="display:flex;gap:12px;align-items:center;flex-wrap:wrap"><div style="display:grid;gap:8px;width:100%"><span id="cat-pick-lbl" style="font-size:13px;font-weight:600">Move to category</span><div role="radiogroup" aria-labelledby="cat-pick-lbl" style="display:flex;gap:6px;flex-wrap:wrap">${catOpts.filter(c=>!['Transfers','Credit card payments'].includes(c)).map(c=>{const a=S.editCat===c;return html`<button type="button" role="radio" aria-checked=${a} onClick=${()=>A.setState({editCat:c})} class="hv-border" style=${`${chip(a).replace('#cdd6ca','#dfe5db')};border-radius:999px;padding:6px 12px;font-size:13px;font-weight:600;cursor:pointer;transition:background .15s`}>${c}</button>`;})}</div></div><button type="button" role="switch" aria-checked=${S.editRule} onClick=${()=>A.setState({editRule:!S.editRule})} style="display:flex;align-items:center;gap:10px;border:0;background:none;padding:4px 0;font-size:14px;cursor:pointer;color:#183c35;text-align:left"><${Switch} on=${S.editRule}/>Always use this for “${nm}”</button><div style="display:flex;gap:8px;margin-left:auto"><button onClick=${()=>A.setState({editTx:''})} style=${btn+';padding:8px 14px'}>Cancel</button><button onClick=${saveEdit} style=${btnDark+';padding:8px 14px'}>Save</button></div></div></td></tr>`:null}`;})}</tbody></table></div>
   ${!tr.length?html`<p style="margin:0;padding:24px 0;text-align:center;color:#5a6b63">No transactions match these filters.</p>`:null}
   <div style="display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap;font-size:13px;color:#5a6b63"><span>Showing ${Math.min(S.limit,tr.length)} of ${tr.length.toLocaleString()}. Card payments and transfers don’t count as spending.</span>${tr.length>S.limit?html`<button onClick=${()=>A.setState({limit:S.limit+40})} style=${btn+';padding:9px 14px'}>Show 40 more</button>`:null}</div>
  </section>`;
}

// ===================== CHAT =====================
export function Chat({A,S,J,all,pad,gap,mobile}){
 const byId=Object.fromEntries(all.map(t=>[String(t.id),t])),lastMonth=mLong(mk(new Date(J.TODAY.getFullYear(),J.TODAY.getMonth()-1,1))),insts=[...new Set(J.accounts.map(a=>a.institution))],months=J.months(J.firstDate,J.todayIso).length;
 const instText=insts.length?insts.length===1?insts[0]:`${insts.slice(0,-1).join(', ')} and ${insts.at(-1)}`:'your accounts';
 const starters=[['Spending','Where did my money go last month?'],['Bills','Which subscriptions went up in price, and what do they cost me per year?'],['What-if','What if I cut dining out by 30%?'],['Trends','How has my savings rate changed over the last 12 months?']];
 const send=e=>{e?.preventDefault();A.ask(S.input);};
 const aiOff=S.status&&S.status.ai===false;
 return html`<div style=${`display:grid;grid-template-columns:${mobile?'minmax(0,1fr)':'minmax(0,1fr) 300px'};gap:${gap};align-items:start`}>
  <section aria-label="Conversation" style=${`background:#fff;border:1px solid #e2e7df;border-radius:16px;display:flex;flex-direction:column;min-height:${mobile?'calc(100vh - 230px)':'calc(100vh - 190px)'};min-width:0`}>
   <div role="log" aria-live="polite" aria-busy=${S.loading} style=${`flex:1;padding:${pad};display:flex;flex-direction:column;gap:22px`}>
    ${!S.msgs.length&&!S.loading?html`<div style="display:grid;gap:18px;padding:20px 0 8px;max-width:640px">
     <span aria-hidden="true" style="width:48px;height:48px;border-radius:14px;background:#183c35;color:#d1e5a7;display:grid;place-items:center;font-size:22px">✦</span>
     <div><h2 style="font:400 29px/1.2 'Instrument Serif',serif;letter-spacing:-.6px;margin:0">What would you like to know?</h2><p style="margin:6px 0 0;font-size:15px;color:#5a6b63;text-wrap:pretty">I can see ${months} month${months===1?'':'s'} of transactions across ${instText}. I can draw charts, cite the exact transactions, and run what-if scenarios.</p></div>
     ${aiOff?html`<p role="note" style="margin:0;background:#fbefd9;border:1px solid #f0dcb4;border-radius:12px;padding:12px 14px;font-size:14px;color:#5c4319">Chat isn’t switched on yet. Add <b>ANTHROPIC_API_KEY</b> in Vercel → Project Settings → Environment Variables, then redeploy.</p>`:null}
     <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,240px),1fr));gap:10px">${starters.map(([tag,q])=>html`<button onClick=${()=>A.ask(q)} class="rb" style="--f:#f7f9f4;--f2:#fff;--r:#e2e7df;text-align:left;border-radius:12px;padding:13px;cursor:pointer;display:grid;gap:4px"><span style="font-size:12px;font-weight:700;letter-spacing:.6px;color:#4d6b45;text-transform:uppercase">${tag}</span><span style="font-size:14px;font-weight:600;color:#183c35">${q}</span></button>`)}</div>
    </div>`:null}
    ${S.msgs.map(m=>{if(m.role==='user')return html`<div key=${m.id} style="align-self:flex-end;max-width:80%;background:#183c35;color:#fff;border-radius:16px 16px 4px 16px;padding:11px 15px;font-size:15px;line-height:1.5;white-space:pre-wrap;overflow-wrap:anywhere">${m.text}</div>`;
     const ch=chartView(A,J,m.chart),saved=S.saved.some(x=>x.id==='ai'+m.id),cites=(m.citations||[]).map(id=>byId[id]).filter(Boolean);let sc=null;
     if(m.scenario){const b=J.projection({}),x=J.projection({incomeChange:m.scenario.monthlyChange}),lo=Math.min(...b.sc,...x.sc),hi=Math.max(...b.sc,...x.sc);sc={title:m.scenario.title,base:A.money(b.sc.at(-1)),scen:A.money(x.sc.at(-1)),diff:(x.sc.at(-1)>=b.sc.at(-1)?'+':'−')+A.money(Math.abs(x.sc.at(-1)-b.sc.at(-1))),baseD:J.linePath(b.sc,560,90,6,lo,hi).d,scD:J.linePath(x.sc,560,90,6,lo,hi).d,open:()=>A.go('projections',{incChg:Math.max(-1500,Math.min(1500,Math.round(m.scenario.monthlyChange/50)*50)),oneOff:0})};}
     return html`<article key=${m.id} style="display:grid;gap:12px;max-width:100%;animation:jsfin .25s ease-out">
      <div style="display:flex;gap:10px;align-items:flex-start"><span aria-hidden="true" style="width:28px;height:28px;border-radius:8px;background:#183c35;color:#d1e5a7;display:grid;place-items:center;font-size:13px;flex:none;margin-top:2px">✦</span><div style="display:grid;gap:8px;min-width:0;flex:1">${paras(m.answer).map(p=>html`<p style=${`margin:0;font-size:15px;line-height:1.6;color:${m.error?'#9a3d2a':'#183c35'};display:flex;gap:8px;text-wrap:pretty`}>${p.bullet?html`<span aria-hidden="true" style="color:#6f9a4e">•</span>`:null}<span>${p.segs.map(sg=>html`<span style=${`font-weight:${sg.w}`}>${sg.t}</span>`)}</span></p>`)}</div></div>
      ${ch?html`<figure style=${`margin:0 0 0 ${mobile?0:38}px;border:1px solid #e2e7df;border-radius:12px;padding:14px;display:grid;gap:10px`}><figcaption style="font:600 14px 'Geist',sans-serif">${ch.title}</figcaption>
       ${ch.isBar?html`<div role="img" aria-label=${ch.aria} style="height:160px;display:flex;align-items:flex-end;gap:6px;border-bottom:1px solid #e2e7df">${ch.bars.map(b=>html`<div style="flex:1;min-width:0;height:100%;display:flex;flex-direction:column;justify-content:flex-end;align-items:center;gap:4px"><span style="font-size:11px;font-weight:600;font-variant-numeric:tabular-nums;white-space:nowrap">${b.v}</span><div style=${`width:100%;max-width:40px;background:${b.color};border-radius:4px 4px 0 0;height:${b.h}%`}></div></div>`)}</div>`:html`<svg viewBox="0 0 560 160" preserveAspectRatio="none" role="img" aria-label=${ch.aria} style="width:100%;height:160px;display:block"><path d=${ch.area} fill="#d1e5a7" fill-opacity=".45"></path><path d=${ch.d} fill="none" stroke="#315e4e" stroke-width="2.5" vector-effect="non-scaling-stroke"></path></svg>`}
       <div aria-hidden="true" style="display:flex;gap:6px">${ch.labels.map(l=>html`<span style="flex:1;min-width:0;text-align:center;font-size:11px;color:#5a6b63;overflow:hidden;white-space:nowrap;text-overflow:ellipsis">${l}</span>`)}</div></figure>`:null}
      ${sc?html`<div style=${`margin-left:${mobile?0:38}px;background:#f0f4e8;border:1px solid #dfe6d6;border-radius:12px;padding:14px;display:grid;gap:10px`}><div style="font-size:12px;font-weight:700;letter-spacing:.6px;color:#4d6b45;text-transform:uppercase">What-if · 12 months</div><div style="font:600 15px 'Geist',sans-serif">${sc.title}</div><div style="display:flex;gap:24px;flex-wrap:wrap">${[['Current path',sc.base,''],['With this change',sc.scen,'color:#2f5d3a'],['Difference',sc.diff,'']].map(([l,v,c])=>html`<div><div style="font-size:12px;color:#4d5d55">${l}</div><b style=${`font:400 24px/1.1 'Instrument Serif',serif;${c}`}>${v}</b></div>`)}</div><svg viewBox="0 0 560 90" preserveAspectRatio="none" aria-hidden="true" style="width:100%;height:90px"><path d=${sc.baseD} fill="none" stroke="#6b7a72" stroke-width="2" stroke-dasharray="5 4" vector-effect="non-scaling-stroke"></path><path d=${sc.scD} fill="none" stroke="#315e4e" stroke-width="3" vector-effect="non-scaling-stroke"></path></svg><${LinkPill} label="Try it in Projections" extra="justify-self:start" onClick=${sc.open}/></div>`:null}
      ${cites.length?html`<div style=${`margin-left:${mobile?0:38}px;border:1px solid #e2e7df;border-radius:12px;overflow:hidden`}><div style="padding:8px 12px;background:#f5f7f2;font-size:12px;font-weight:700;color:#3d4d45">Cited transactions</div>${cites.map(t=>html`<button onClick=${()=>A.go('transactions',{q:t.name,tCat:'',tType:'all',view:'',range:'24m'})} class="hv-soft" style="width:100%;display:grid;grid-template-columns:70px minmax(0,1fr) auto;gap:10px;align-items:center;text-align:left;border:0;border-top:1px solid #eef1ea;background:#fff;padding:9px 12px;font-size:13px;cursor:pointer"><span style="color:#5a6b63;font-variant-numeric:tabular-nums">${A.fmtDate(t.date)}</span><span style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap"><b>${title(t.name)}</b> <span style="color:#5a6b63">· ${t.category}</span></span><b style=${`font-variant-numeric:tabular-nums;color:${t.amount<0?'#2f5d3a':'#183c35'}`}>${(t.amount<0?'+':'−')+A.money(Math.abs(t.amount),2)}</b></button>`)}</div>`:null}
      <div style=${`margin-left:${mobile?0:38}px;display:flex;gap:8px;flex-wrap:wrap`}>
       ${!m.error?html`<button onClick=${()=>A.saveMsg(m)} disabled=${saved} style="background:#fff;border:1px solid #cdd6ca;padding:6px 12px;border-radius:8px;font-size:13px;font-weight:600;color:#183c35;cursor:pointer">${saved?'✓ Pinned to Overview':'＋ Pin to Overview'}</button>`:null}
       ${(m.followups||[]).map(q=>html`<button onClick=${()=>A.ask(q)} class="hv-e8" style="background:#f3f6ef;border:1px solid #dfe6d9;padding:6px 12px;border-radius:20px;font-size:13px;color:#2f4a3f;cursor:pointer;text-align:left">${q}</button>`)}
      </div>
     </article>`;})}
    ${S.loading?html`<div style="display:flex;gap:10px;align-items:center;color:#5a6b63;font-size:14px"><span aria-hidden="true" style="width:28px;height:28px;border-radius:8px;background:#183c35;color:#d1e5a7;display:grid;place-items:center;font-size:13px">✦</span><span aria-hidden="true" style="display:inline-flex;gap:4px">${[0,1,2].map(i=>html`<i style=${`width:6px;height:6px;border-radius:3px;background:#315e4e;animation:jsfdot 1s ${i*.15}s infinite ease-in-out`}></i>`)}</span><span>Reading your transactions…</span></div>`:null}
   </div>
   <form onSubmit=${send} style=${`position:sticky;bottom:${mobile?'80px':'0'};background:#fff;border-top:1px solid #e2e7df;border-radius:0 0 16px 16px;padding:12px;display:flex;gap:10px;align-items:flex-end`}>
    <label class="rbwrap" style="flex:1;min-width:0;position:relative;display:block"><span class="sr">Message</span><span aria-hidden="true" class="rbglow" style="inset:3px;border-radius:12px;filter:blur(12px)"></span><textarea value=${S.input} onInput=${e=>{A.setState({input:e.target.value});e.target.style.height='auto';e.target.style.height=Math.min(140,e.target.scrollHeight)+'px';}} onKeyDown=${e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();send();}}} rows="1" maxlength="4000" placeholder="Ask about spending, bills, savings, or a what-if…" class="rb" style="--f:#fafbf8;--f2:#fff;--r:#cdd6ca;width:100%;position:relative;display:block;resize:none;border-radius:12px;outline:none;padding:11px 13px;font-size:15px;line-height:1.4;min-height:46px;max-height:140px"></textarea></label>
    <button type="submit" disabled=${S.loading||!S.input.trim()} style="background:#183c35;color:#fff;border:0;border-radius:10px;padding:0 18px;height:46px;font-weight:700;font-size:14px;cursor:pointer">Send</button>
   </form>
  </section>
  ${!mobile?html`<aside aria-label="Chat tools" style="display:grid;gap:14px;position:sticky;top:20px">
   <div style="background:#183c35;color:#fff;border-radius:14px;padding:18px;display:grid;gap:10px"><div style="font:600 16px 'Geist',sans-serif">Monthly recap</div><p style="margin:0;font-size:13px;color:#cfe0c9;line-height:1.5">A summary of last month: income, spending, what changed and what to watch.</p><button onClick=${()=>A.ask(`Give me my ${lastMonth} monthly recap: income, spending and savings rate versus the month before, the biggest categories, notable transactions, budget overruns and any subscription changes. Include a chart.`)} class="rb" style="--f:#d1e5a7;--r:#d1e5a7;justify-self:start;color:#183c35;border-radius:10px;padding:8px 14px;font-weight:700;font-size:13px;cursor:pointer">Get ${lastMonth.split(' ')[0]} recap</button></div>
   <div style="background:#fff;border:1px solid #e2e7df;border-radius:14px;padding:18px;display:grid;gap:10px"><div style="font:600 14px 'Geist',sans-serif">What the assistant can see</div><ul style="margin:0;padding:0 0 0 18px;display:grid;gap:4px;font-size:13px;color:#3d4d45"><li>${J.accounts.length} account${J.accounts.length===1?'':'s'}, read-only</li><li>${J.tx.length.toLocaleString()} transactions, ${new Date(`${J.firstDate}T12:00:00`).toLocaleDateString('en-CA',{month:'short',year:'numeric'})} to today</li><li>Budgets, bills and subscriptions</li><li>Your category rules and loans</li></ul><p style="margin:0;font-size:12px;color:#5a6b63;line-height:1.5">A summary of this data is sent to Anthropic’s Claude model only when you ask a question. Answers are observations, not financial advice.</p></div>
   ${S.msgs.length?html`<button onClick=${()=>A.setState({msgs:[]})} style=${btn}>New conversation</button>`:null}
  </aside>`:S.msgs.length?html`<button onClick=${()=>A.setState({msgs:[]})} style=${btn}>New conversation</button>`:null}
 </div>`;
}

// ===================== SETTINGS =====================
export function Settings({A,S,J,pad,gap,mobile}){
 const E={...A.committedSettings(),...(S.draft||{})},dk=A.dirtyKeys(),tabKeys={connections:['env'],rules:['budgets','rules'],display:['density','reduceMotion']};
 const tabs=[['connections','Connections'],['rules','Categories & budgets'],['display','Display'],['plaid','Plaid'],['security','Security']];
 const tab=S.setTab;
 return html`
  <div role="tablist" aria-label="Settings sections" style="display:flex;gap:4px;flex-wrap:wrap;border-bottom:1px solid #e2e7df">
   ${tabs.map(([id,label])=>{const a=tab===id,dirty=(tabKeys[id]||[]).some(k=>dk.includes(k));return html`<button role="tab" onClick=${()=>A.setState({setTab:id})} aria-selected=${a} style=${`border:0;background:none;padding:10px 14px;font-size:14px;font-weight:${a?700:500};color:${a?'#183c35':'#4f5f57'};border-bottom:3px solid ${a?'#315e4e':'transparent'};margin-bottom:-1px;cursor:pointer;display:flex;align-items:center;gap:7px`}>${label}${dirty?html`<span aria-label="unsaved" style="width:7px;height:7px;border-radius:50%;background:#c47a4e"></span>`:null}</button>`;})}
   <span style="margin-left:auto;align-self:center;font-size:13px;color:#5a6b63;padding:0 4px">${dk.length?'':S.savedAt?`Saved ${S.savedAt}`:''}</span>
  </div>
  ${tab==='connections'?Connections({A,S,J,E,pad}):null}
  ${tab==='rules'?Rules({A,S,J,E,pad,gap}):null}
  ${tab==='display'?Display({A,E,pad}):null}
  ${tab==='plaid'?Plaid({A,S,pad}):null}
  ${tab==='security'?Security({A,S,pad}):null}
  ${dk.length?html`<div role="region" aria-label="Unsaved changes" style=${`position:sticky;bottom:${mobile?'88px':'16px'};z-index:25;background:#183c35;color:#fff;border-radius:14px;padding:12px 12px 12px 18px;display:flex;align-items:center;gap:12px;flex-wrap:wrap;box-shadow:0 14px 36px #183c3540;animation:jsfin .2s ease-out`}><span aria-hidden="true" style="width:8px;height:8px;border-radius:50%;background:#d1e5a7;flex:none"></span><div style="flex:1;min-width:180px"><b style="font-size:14px">Unsaved changes</b><div style="font-size:13px;color:#cfe0c9">${A.dirtyText()} · nothing changes until you save</div></div><button onClick=${()=>{A.setState({draft:null});A.toast('Changes discarded');}} class="hv-ghost" style="background:transparent;border:1px solid #ffffff59;color:#fff;padding:9px 16px;border-radius:10px;font-size:14px;font-weight:600;cursor:pointer;min-height:42px">Discard</button><button onClick=${()=>{A.applyDraft(S.draft);A.toast('Settings saved');}} class="hv-lime" style="background:#d1e5a7;border:0;color:#183c35;padding:9px 18px;border-radius:10px;font-size:14px;font-weight:700;cursor:pointer;min-height:42px">Save changes</button></div>`:null}`;
}
function Connections({A,S,J,E,pad}){
 const conns=S.data.connections||[],demo=S.mode==='demo';
 return html`<section style=${card(pad,'gap:16px')}>
  <div style="display:flex;justify-content:space-between;align-items:flex-start;gap:12px;flex-wrap:wrap"><div><${H2}>Connected institutions</${H2}><${Sub}>Read-only access through Plaid. No payments or transfers.</${Sub}></div>
   <div style="display:flex;gap:8px;flex-wrap:wrap"><div role="group" aria-label="Plaid environment" style="display:flex;gap:2px;background:#edf0e9;border-radius:9px;padding:3px">${[['sandbox','Sandbox'],['production','Production']].map(([id,label])=>{const a=E.env===id;return html`<button onClick=${()=>A.setDraft('env',id)} aria-pressed=${a} style=${`border:0;border-radius:6px;padding:7px 12px;font-size:13px;font-weight:${a?700:500};background:${a?(id==='sandbox'?'#2f6a8c':'#3f6a39'):'transparent'};color:${a?'#fff':'#4f5f57'};cursor:pointer`}>${label}</button>`;})}</div>
    <button onClick=${()=>A.sync()} disabled=${S.busy==='sync'} style=${btn}>${S.busy==='sync'?'Syncing…':'↻ Sync all'}</button><button onClick=${()=>A.connect()} disabled=${S.busy==='connect'} style=${btnDark}>＋ Connect account</button></div></div>
  <p style="margin:0;font-size:13px;color:#3d4d45">${S.env==='sandbox'?'Sandbox uses Plaid’s test banks. Nothing here touches a real account.':'Production connects to your real banks.'} ${E.env!==S.env?html`<b>Save to switch to ${E.env==='sandbox'?'Sandbox':'Production'}.</b>`:''}</p>
  ${conns.length?conns.map(c=>{const fmt=d=>d?new Date(`${d}T12:00:00`).toLocaleDateString('en-CA',{month:'short',year:'numeric'}):'';return html`<div style="display:flex;gap:12px;align-items:center;padding:12px 0;border-top:1px solid #eef1ea;flex-wrap:wrap"><span aria-hidden="true" style="width:40px;height:40px;border-radius:11px;display:grid;place-items:center;background:#fff;border:1px solid #e2e7df;flex:none;overflow:hidden"><${BankLogo} institution=${c.institution} size=${25}/></span><div style="flex:1;min-width:160px"><div style="font-weight:600">${c.institution}${c.imported?` · ${c.accountName} ••${c.mask}`:''}</div><div style="font-size:13px;color:#5a6b63">${c.imported?`${c.transactions.toLocaleString()} transactions from ${c.statements} statement${c.statements===1?'':'s'} · ${fmt(c.from)} to ${fmt(c.to)}`:`${J.accounts.filter(a=>a.institution===c.institution).length} account(s) · ${c.synced?`last synced ${new Date(c.synced).toLocaleString('en-CA',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})}`:'waiting for first sync'}`}</div></div>${c.imported?html`<span style="font-size:12px;font-weight:700;background:#e3ecf6;color:#2c5577;padding:3px 9px;border-radius:20px">Imported</span><button onClick=${()=>A.removeImport(c)} style=${btn+';padding:8px 12px;color:#9a3d2a;border-color:#efcfc5'}>Remove</button>`:html`<span style=${`font-size:12px;font-weight:700;background:${c.synced?'#e6f0dc':'#fbefd9'};color:${c.synced?'#2f5d3a':'#7a5520'};padding:3px 9px;border-radius:20px`}>${c.synced?'Connected':'Pending'}</span><button onClick=${()=>A.connect(c.id)} style=${btn+';padding:8px 12px'}>Reconnect</button>`}</div>`;})
   :html`<p style="margin:0;padding:16px;background:#f7f9f4;border-radius:10px;font-size:14px;color:#3d4d45">${demo?'You’re viewing sample accounts. ':''}No banks are connected in ${S.env==='sandbox'?'Sandbox':'Production'} yet. ${S.status?.connected?'Use Connect account to link one.':html`First save and verify your Plaid credentials in the <button onClick=${()=>A.setState({setTab:'plaid'})} style="border:0;background:none;padding:0;color:#2f5d3a;text-decoration:underline;cursor:pointer;font:inherit">Plaid tab</button>.`}</p>`}
  <details><summary style="cursor:pointer;font-size:13px;font-weight:600">Privacy & how syncing works</summary><p style="font-size:13px;color:#3d4d45;line-height:1.6">The app requests Plaid’s Transactions product only. Access tokens are encrypted before they’re stored. Sync downloads what Plaid already has; it doesn’t force a real-time bank refresh. Use Reconnect when a bank asks you to sign in again. For OAuth banks, register this site’s address in Plaid and finish linking in the same browser tab.</p></details>
 </section>${ImportPanel({A,S,pad})}`;
}
function ImportPanel({A,S,pad}){
 const imp=S.importing,results=imp?.results||[],ok=results.filter(r=>r.ok).length,failed=results.filter(r=>!r.ok);
 return html`<section aria-labelledby="imp-h" style=${card(pad,'gap:14px')}>
  <div style="display:flex;justify-content:space-between;align-items:flex-start;gap:12px;flex-wrap:wrap"><div><${H2} id="imp-h">Import statements</${H2}><${Sub}>For banks Plaid can’t connect. Upload RBC credit card statements (PDF), or a ZIP of them. Each statement is checked against its own totals before anything is saved, and re-uploading never creates duplicates.</${Sub}></div>
   <label style=${btnDark+';display:inline-flex;align-items:center;gap:8px;'+(imp?.running?'opacity:.6;pointer-events:none':'')}><input type="file" accept=".pdf,.zip,application/pdf,application/zip" multiple onChange=${e=>{const files=[...e.target.files];e.target.value='';A.importStatements(files);}} style="position:absolute;width:1px;height:1px;opacity:0"/>${imp?.running?'Importing…':'＋ Choose PDFs or ZIP'}</label></div>
  ${imp?html`<div aria-live="polite" style="display:grid;gap:8px">
   <div style="display:flex;justify-content:space-between;gap:10px;font-size:14px;flex-wrap:wrap"><b>${imp.running?`Reading ${imp.done} of ${imp.total} statements…`:`Done: ${ok} of ${imp.total} statements imported${imp.added!=null?` · ${imp.added.toLocaleString()} new transactions`:''}`}</b>${!imp.running?html`<button onClick=${()=>A.setState({importing:null})} style="border:0;background:none;color:#2f5d3a;font-size:13px;font-weight:600;cursor:pointer;text-decoration:underline">Clear</button>`:null}</div>
   <div style="height:8px;background:#edf1e9;border-radius:5px;overflow:hidden"><div style=${`height:100%;width:${imp.total?imp.done/imp.total*100:0}%;background:#315e4e;border-radius:5px;transition:width .2s`}></div></div>
   ${failed.length?html`<div style="display:grid;gap:4px;background:#fbefeb;border:1px solid #efcfc5;border-radius:10px;padding:10px 12px;font-size:13px;color:#7a2f20">${failed.map(r=>html`<div><b>${r.name}</b>: ${r.message}</div>`)}</div>`:null}
  </div>`:null}
  <p style="margin:0;font-size:12px;color:#5a6b63">Only the transactions and balances are kept; the PDFs aren’t stored. Imported data appears under Production or Sandbox, whichever you’re using now (${S.env==='sandbox'?'Sandbox':'Production'}).</p>
 </section>`;
}
function Rules({A,S,J,E,pad,gap}){
 const eb={...J.defaultBudgets,...E.budgets},rules=Object.entries(E.rules||{});
 const [newCat,setNewCat]=[S.newBudgetCat||'',v=>A.setState({newBudgetCat:v})];
 const cats=[...new Set(J.tx.filter(t=>['expense','refund'].includes(t.kind)).map(t=>t.category))].filter(c=>!(c in eb)&&!['Rent','Loan payments','Bank fees'].includes(c)).sort();
 return html`<div style=${grid2(gap,420)}>
  <section style=${card(pad,'gap:12px')}><div><${H2}>Monthly budgets</${H2}><${Sub}>Used by Budget vs actual and the assistant. Starting values are your recent monthly average.</${Sub}></div>
   ${Object.entries(eb).map(([name,v])=>html`<div style="display:flex;justify-content:space-between;align-items:center;gap:12px;padding:6px 0;border-top:1px solid #eef1ea;font-size:14px;font-weight:600"><span>${name}</span><div style="display:flex;align-items:center;border:1px solid #cdd6ca;border-radius:10px;overflow:hidden;background:#fff;flex:none"><button type="button" onClick=${()=>A.setDraft('budgets',b=>({...b,[name]:Math.max(0,v-10)}))} aria-label=${`Lower ${name} budget by $10`} class="hv-e6" style="width:38px;height:40px;border:0;border-right:1px solid #e2e7df;background:#f5f8f1;cursor:pointer;font-size:17px;color:#183c35">−</button><span aria-hidden="true" style="padding-left:10px;color:#5a6b63;font-weight:400">$</span><input type="number" min="0" step="10" value=${v} onInput=${e=>{const x=Math.max(0,+e.target.value||0);A.setDraft('budgets',b=>({...b,[name]:x}));}} aria-label=${`${name} monthly budget`} style="width:72px;border:0;padding:8px 10px 8px 4px;font-size:14px;font-weight:600;text-align:right;outline:none;color:#183c35;font-variant-numeric:tabular-nums;background:transparent"/><button type="button" onClick=${()=>A.setDraft('budgets',b=>({...b,[name]:v+10}))} aria-label=${`Raise ${name} budget by $10`} class="hv-e6" style="width:38px;height:40px;border:0;border-left:1px solid #e2e7df;background:#f5f8f1;cursor:pointer;font-size:17px;color:#183c35">+</button></div></div>`)}
   ${cats.length?html`<div style="display:flex;gap:8px;align-items:flex-end;flex-wrap:wrap;border-top:1px solid #eef1ea;padding-top:10px"><${Select} value=${newCat} options=${[{value:'',label:'Add a category…'},...cats.map(c=>({value:c,label:c}))]} onChange=${setNewCat} label="Add a budget" hideLabel=${true} icon="tag" minWidth="200px"/><button onClick=${()=>{if(newCat){A.setDraft('budgets',b=>({...b,[newCat]:100}));setNewCat('');}}} disabled=${!newCat} style=${btn+';border-radius:10px;min-height:42px'}>Add</button></div>`:null}
  </section>
  <section style=${card(pad,'gap:12px')}><div><${H2}>Category rules</${H2}><${Sub}>Created when you recategorize a transaction with “Always use this”</${Sub}></div>
   ${!rules.length?html`<p style="margin:0;padding:16px;background:#f7f9f4;border-radius:10px;font-size:14px;color:#3d4d45">No rules yet. In Transactions, select any category tag to change it and create a rule.</p>`:null}
   ${rules.map(([m,c])=>html`<div style="display:flex;justify-content:space-between;align-items:center;gap:10px;padding:8px 0;border-top:1px solid #eef1ea;font-size:14px"><span><b>${title(m)}</b> → ${c}</span><button onClick=${()=>A.setDraft('rules',r=>{const r2={...r};delete r2[m];return r2;})} aria-label=${`Delete rule for ${title(m)}`} style="background:#fff;border:1px solid #e3c3ba;color:#9a3d2a;padding:6px 10px;border-radius:8px;font-size:13px;cursor:pointer">Delete</button></div>`)}
   ${Object.keys(S.overrides||{}).length?html`<div style="display:flex;justify-content:space-between;align-items:center;gap:10px;padding:8px 0;border-top:1px solid #eef1ea;font-size:13px;color:#3d4d45"><span>${Object.keys(S.overrides).length} one-off change${Object.keys(S.overrides).length>1?'s':''} to single transactions</span><button onClick=${()=>{A.setState({overrides:{}});A.toast('One-off category changes cleared');}} style="background:#fff;border:1px solid #e3c3ba;color:#9a3d2a;padding:6px 10px;border-radius:8px;font-size:13px;cursor:pointer">Clear</button></div>`:null}
  </section></div>`;
}
function Display({A,E,pad}){
 return html`<section style=${card(pad,'gap:18px;max-width:640px')}>
  <div><${H2}>Display</${H2}></div>
  <div style="display:grid;gap:8px"><span id="dens-lbl" style="font-size:14px;font-weight:600">Density</span><div role="radiogroup" aria-labelledby="dens-lbl" style="display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,240px),1fr));gap:10px">${[['comfortable','Comfortable','More breathing room. Best for reading.'],['compact','Compact','Tighter cards and table rows. Fits more on screen.']].map(([id,label,note])=>{const sel=E.density===id;return html`<button type="button" role="radio" aria-checked=${sel} onClick=${()=>A.setDraft('density',id)} class="hv-border2" style=${`display:flex;gap:14px;align-items:center;text-align:left;border:${sel?'2px':'1px'} solid ${sel?'#315e4e':'#e2e7df'};border-radius:12px;padding:14px;cursor:pointer;background:${sel?'#f3f6ef':'#fff'};color:#183c35;transition:border-color .15s`}><span aria-hidden="true" style=${`width:22px;height:22px;border-radius:50%;border:2px solid ${sel?'#315e4e':'#9fb09a'};display:grid;place-items:center;flex:none`}><span style=${`width:10px;height:10px;border-radius:50%;background:${sel?'#315e4e':'transparent'}`}></span></span><span style="flex:1;min-width:0"><b style="display:block;font-size:14px">${label}</b><span style="font-size:13px;color:#5a6b63">${note}</span></span><span aria-hidden="true" style=${`display:grid;gap:${id==='compact'?'3px':'7px'};width:46px;flex:none`}><i style="height:6px;border-radius:3px;background:#b9c6b4"></i><i style="height:6px;border-radius:3px;background:#cfdccb"></i><i style="height:6px;border-radius:3px;background:#cfdccb"></i></span></button>`;})}</div></div>
  <button type="button" role="switch" aria-checked=${E.reduceMotion} onClick=${()=>A.setDraft('reduceMotion',v=>!v)} style="display:flex;justify-content:space-between;align-items:center;gap:14px;border:1px solid #e2e7df;border-radius:12px;background:#fff;padding:14px;cursor:pointer;text-align:left;color:#183c35"><span><b style="display:block;font-size:14px">Reduce motion</b><span style="font-size:13px;color:#5a6b63">Turns off animations. Also follows your system setting automatically.</span></span><${Switch} on=${E.reduceMotion}/></button>
 </section>`;
}
function Plaid({A,S,pad}){
 const env=S.env,envName=env==='sandbox'?'Sandbox':'Production',saved=S.plaid?.environments?.[env],connected=!!saved?.connected,locked=connected&&!S.plaidEditing,msg=S.plaidMsg;
 const submit=async e=>{e.preventDefault();const f=e.currentTarget;A.setState({plaidMsg:{text:`Testing these credentials with Plaid ${env}…`},busy:'plaid'});try{await A.api('/api/plaid-config',{clientId:f.clientId.value,secret:f.secret.value});f.reset();const plaid=await A.api('/api/plaid-config'),status=await A.api(A.envPath('/api/status'));A.setState({plaid,status,plaidEditing:false,plaidMsg:{text:`Connected to Plaid ${env}.`}});}catch(err){A.setState({plaidMsg:{text:`Could not connect to Plaid ${env}: ${err.message}`,error:true}});}finally{A.setState({busy:''});}};
 const verify=async()=>{A.setState({plaidMsg:{text:`Verifying the saved ${env} configuration…`},busy:'plaid'});try{await A.api('/api/plaid-config/verify',{});const plaid=await A.api('/api/plaid-config'),status=await A.api(A.envPath('/api/status'));A.setState({plaid,status,plaidMsg:{text:'Verified.'}});}catch(err){A.setState({plaidMsg:{text:`Could not connect to Plaid ${env}: ${err.message}`,error:true}});}finally{A.setState({busy:''});}};
 const status=connected?['Connected','#e6f0dc','#2f5d3a']:saved?.configured?['Verification needed','#fbefd9','#7a5520']:['Not configured','#eef1ea','#3d4d45'];
 const note=msg?msg.text:connected&&!S.plaidEditing?`Connected to Plaid ${env}. Last verified ${new Date(saved.verifiedAt).toLocaleString()}.`:saved?.configured&&!S.plaidEditing?'Credentials are stored, but this connection has not been verified yet.':'';
 const lockedSt='border:1px solid #d5ded1;background:#eef2eb;border-radius:8px;padding:11px;font-size:14px',openSt='border:1px solid #cdd6ca;background:#fafbf8;border-radius:8px;padding:11px;font-size:14px';
 return html`<section style=${card(pad,'gap:16px;max-width:760px')}>
  <div style="display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap"><div><${H2}>Plaid credentials · ${envName}</${H2}><${Sub}>Tested against Plaid before saving. Saved values are encrypted and never shown again. Switch environment in Connections.</${Sub}></div><span style=${`font-size:12px;font-weight:700;background:${status[1]};color:${status[2]};padding:4px 10px;border-radius:20px;align-self:flex-start;white-space:nowrap`}>${status[0]}</span></div>
  <form onSubmit=${submit} autocomplete="off" style="display:grid;gap:16px">
   <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,240px),1fr));gap:12px">
    <label style="display:grid;gap:6px;font-size:14px;font-weight:600">Client ID${locked?html`<input type="password" value="saved-securely" disabled style=${lockedSt}/>`:html`<input name="clientId" type="password" autocomplete="off" required minlength="8" maxlength="512" placeholder=${saved?.configured?'Enter both values to replace':'Enter client ID'} class="fi" style=${openSt}/>`}</label>
    <label style="display:grid;gap:6px;font-size:14px;font-weight:600">${envName} secret${locked?html`<input type="password" value="saved-securely" disabled style=${lockedSt}/>`:html`<input name="secret" type="password" autocomplete="new-password" required minlength="8" maxlength="512" placeholder=${saved?.configured?'Enter both values to replace':'Enter environment secret'} class="fi" style=${openSt}/>`}</label>
   </div>
   ${note?html`<p role=${msg?.error?'alert':'status'} style=${`margin:0;font-size:13px;padding:10px 12px;border-radius:10px;background:${msg?.error?'#fbefeb':'#f3f6ef'};color:${msg?.error?'#7a2f20':'#2f4a3f'}`}>${note}</p>`:null}
   <div style="display:flex;gap:8px;flex-wrap:wrap">${locked?html`<button type="button" onClick=${()=>A.setState({plaidEditing:true,plaidMsg:null})} style=${btn}>Update configuration</button>`:html`<button type="submit" disabled=${S.busy==='plaid'} style=${btnDark}>Test & save configuration</button>${S.plaidEditing?html`<button type="button" onClick=${()=>A.setState({plaidEditing:false,plaidMsg:null})} style=${btn}>Cancel</button>`:null}`}${saved?.configured&&!connected&&!S.plaidEditing?html`<button type="button" onClick=${verify} disabled=${S.busy==='plaid'} style=${btn}>Verify saved connection</button>`:null}</div>
  </form>
 </section>`;
}
function Security({A,S,pad}){
 const submit=async e=>{e.preventDefault();const f=e.currentTarget;if(f.newPassword.value!==f.confirmPassword.value)return A.setState({pwMsg:'The new passwords do not match.'});if(f.newPassword.value===f.currentPassword.value)return A.setState({pwMsg:'Choose a different password.'});A.setState({pwBusy:true,pwMsg:'Updating your password…'});try{await A.api('/api/auth/change-password',{currentPassword:f.currentPassword.value,newPassword:f.newPassword.value,revokeOtherSessions:true});f.reset();const status=await A.api(A.envPath('/api/status'));A.setState({status,pwMsg:'Password updated. Your other sessions have been signed out.'});}catch(err){A.setState({pwMsg:err.message});}finally{A.setState({pwBusy:false});}};
 const inp='border:1px solid #cdd6ca;background:#fafbf8;border-radius:8px;padding:11px;font-size:14px';
 return html`<form onSubmit=${submit} style=${card(pad,'gap:16px;max-width:760px')}>
  <div><${H2}>Update your password</${H2}><${Sub}>${S.status?.email?`Signed in as ${S.status.email}. `:''}At least 12 characters. Other signed-in sessions will be signed out.</${Sub}></div>
  <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,200px),1fr));gap:12px"><label style="display:grid;gap:6px;font-size:14px;font-weight:600">Current password<input name="currentPassword" type="password" autocomplete="current-password" required maxlength="128" class="fi" style=${inp}/></label><label style="display:grid;gap:6px;font-size:14px;font-weight:600">New password<input name="newPassword" type="password" autocomplete="new-password" required minlength="12" maxlength="128" class="fi" style=${inp}/></label><label style="display:grid;gap:6px;font-size:14px;font-weight:600">Confirm new password<input name="confirmPassword" type="password" autocomplete="new-password" required minlength="12" maxlength="128" class="fi" style=${inp}/></label></div>
  ${S.pwMsg?html`<p role="status" style="margin:0;font-size:13px;color:#3d4d45">${S.pwMsg}</p>`:null}
  <div><button type="submit" disabled=${S.pwBusy} style=${btnDark+';padding:10px 16px'}>Update password</button></div>
 </form>`;
}
